#ifndef CORE_H
#define CORE_H

/***************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************
 * Imported libraries
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/

#include <stdint.h>                                                            // Used for uintX_t
#include <stdlib.h>                                                            // Used for allocate memory dynamic
#include <string.h>                                                            // Used for operations with strings
#include <stdio.h>                                                             // Used for snprintf, ...
#include <byteswap.h>                                                          // Used to swap every bit on a register

/***************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************
 * Standard definitions 
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/

#define INPUT                          0 
#define OUTPUT                         1

#define LOW                            0
#define HIGH                           1
#define TOGGLE                         2
#define FAILURE                        3 

#define EQUAL                          0
#define OR                             1
#define AND                            2

/***************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************
 * Details
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/

#define BUF_SIZE                       300                                     // Number of bytes
#define F_CPU                          40000000                                // CPU frequency in Hertz

/***************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************
 * Macros
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/

/**********************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************//**
 * @brief Reads the value stored in the specified memory-mapped hardware register.
 * 
 * @param[in] REG The address of the register to be read.
 *
 * @return The current 32-bit value stored in the specified register.
 *
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/
#define READ_REGISTER(REG) (*(volatile uint32_t *)(REG))                       

/**********************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************//**
 * @brief Updates the state of a memory-mapped hardware register using the specified logic operation.
 * 
 * @param[in] REG The address of the register to be updated.
 * @param[in] MASK The value to apply to the register.
 * @param[in] OPERATION The logic operation to perform (`|=`, `&=`, `^=`, etc.).
 *
 * @return none
 *
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/
#define UPDATE_REGISTER(REG, MASK, OPERATION) \
                       (*( volatile uint32_t * )(REG) OPERATION (MASK))        

/**********************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************//**
 * @brief Clears all bits in the specified memory-mapped hardware register, effectively setting its value to `0`.
 * 
 * @param[in] REG The address of the register to be cleared.
 *
 * @return none
 *
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/
#define CLEAR_REGISTER(REG)( UPDATE_REGISTER( REG, 0, = ))                     

/**********************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************//**
 * @brief Sets all bits in the specified memory-mapped hardware register, effectively setting its value to `0xFFFF_FFFF`.
 * 
 * @param[in] REG The address of the register to be set.
 *
 * @return none
 *
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/
#define SET_REGISTER(REG)( UPDATE_REGISTER( REG, 0xFFFFFFFF, = ))              // Set to FF all the register

/**********************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************//**
 * @brief Creates a bit mask for the specified bit position.
 * 
 * @param[in] BIT The bit position to set (0–31).
 *
 * @return A value with only the specified bit set to `1`.
 *
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/
#define SET_BIT(BIT)( HIGH << BIT )

/**********************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************//**
 * @brief Creates a bit mask for the specified bit position.
 * 
 * @param[in] BIT The bit position to set (0–31).
 *
 * @return A value with only the specified bit set to `0`.
 *
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/
#define RSET_BIT(BIT)( LOW << BIT )

/**********************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************//**
 * @brief Convert an 8 bit variable to a 32 bit variable, with the correct format. 
 * 
 * @param buf The uint8_t memory block. 
 *  
 * @return none
 * 
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/
static inline uint32_t 
convertTo4Bytes( const uint8_t buf[4] ){
  return ((buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3] );
}

/***************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************
 * Definition file
 **************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/

#endif 

